package com.huariservice.huariia.entities;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.ToString;

/**
 * JPA entity representing the content creator (e.g. a YouTube channel) that owns one or more courses.
 *
 * <p>Mapped to the legacy table {@code autores}.</p>
 */
@Entity
@Table(name = "autores")
@Data
@AllArgsConstructor
@NoArgsConstructor
public class Author {

    /** Surrogate primary key generated by the database. */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @ToString.Include
    private Long id;

    /** Public channel name; must be unique across authors. */
    @Column(name = "nome_canal", length = 100, nullable = false, unique = true)
    @ToString.Include
    private String channelName;

    /** URL of the author's channel; must be unique across authors. */
    @Column(name = "link_canal", length = 254, nullable = false, unique = true)
    private String channelUrl;

    /** Identity-based equality: equal only when both instances are persisted with the same id. */
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Author other)) return false;
        return id != null && id.equals(other.id);
    }

    /** Constant class-based hash, stable before and after the id is generated. */
    @Override
    public int hashCode() {
        return getClass().hashCode();
    }
}